package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class JsonWriter_value_TriageGen2Test {

    private StringWriter out;
    private JsonWriter writer;

    @Before
    public void setUp() {
        out = new StringWriter();
        writer = new JsonWriter(out);
    }









    @Test
    public void testValue_NonFinite_StrictMode_Infinity() throws IOException {
        writer.setLenient(false);
        try {
            writer.value(Double.POSITIVE_INFINITY);
            org.junit.Assert.fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Numeric values must be finite"));
        }
    }










}

